"""Event-time model of the optional global read cache.

The caller owns HBM and network queues.  This class owns cache tag state and
one-request-per-cycle arbitration for each of four fixed cache banks.  Read
arrivals must not precede the last resolved lookup; a later call may not
schedule an earlier write completion.  An instruction scheduler with
overtaking requests must sort cache events before resolving tags.
"""

from collections import OrderedDict
from dataclasses import dataclass
from heapq import heappop, heappush
from typing import Callable

from .resource_calendar import IntervalCalendar

HBM_BYTES = 2**31
LINE_BYTES = 64
WAYS = 4
BANKS = 4
HIT_LATENCY = 8


@dataclass
class TimedCacheTraffic:
    queries: int = 0
    hits: int = 0
    misses: int = 0
    bypass_reads: int = 0
    fills: int = 0
    invalidations: int = 0
    hbm_read_bytes: int = 0
    cache_read_bytes: int = 0
    cache_fill_bytes: int = 0


@dataclass(frozen=True)
class CacheAccess:
    lookup_cycle: int | None
    fill_cycle: int | None
    ready_cycle: int
    hit: bool
    hbm_requested: bool


@dataclass(frozen=True)
class PendingLookup:
    line: int
    cycle: int


class TimedGlobalCache:
    """Deterministic 64 B, four-way, four-bank global cache timing.

    ``miss_ready`` receives ``(aligned_line_address, earliest_hbm_cycle)`` and
    returns the cycle at which HBM has finished returning the complete line.
    The earliest cycle is eight cycles after the bank accepts the lookup.
    ``request_read`` returns ``(data_ready_cycle, hit, hbm_requested)``.  Its
    ready cycle is before the caller's NoC and destination storage service.

    Each miss independently calls ``miss_ready`` even while an identical line
    is pending.  Fills reserve a bank cycle and update LRU only at completion.
    Writes bypass this read cache; call ``schedule_write_invalidate`` with the
    HBM completion cycle for every touched line.

    Capacity zero sends each read directly to HBM. Such reads increment
    ``bypass_reads`` and HBM bytes, without counting a Cache query or miss.
    """

    def __init__(self, capacity_mib: int):
        if type(capacity_mib) is not int or capacity_mib not in (0, 1, 2, 4, 8, 16):
            raise ValueError("Invalid cache capacity")
        self.set_count = capacity_mib * 1024 * 1024 // (LINE_BYTES * WAYS)
        self.sets: dict[int, OrderedDict[int, None]] = {}
        self.traffic = TimedCacheTraffic()
        self._bank_busy = [IntervalCalendar() for _ in range(BANKS)]
        # Heap entries: (completion cycle, priority, order, kind, line, lookup).
        # A fill completes before an invalidation at the same cycle, so a write
        # ending at that cycle leaves the line invalid.
        self._events: list[tuple[int, int, int, str, int, int]] = []
        self._order = 0
        self._resolved_through = -1
        self._last_invalidation: dict[int, int] = {}
        self.last_access: CacheAccess | None = None

    def locate(self, address: int) -> tuple[int, int, int]:
        """Return set, bank and tag; cache-off returns line, -1, -1."""
        line = self._line(address)
        if not self.set_count:
            return line, -1, -1
        set_index = line % self.set_count
        return set_index, set_index % BANKS, line // self.set_count

    @staticmethod
    def _line(address: int) -> int:
        if type(address) is not int or not 0 <= address < HBM_BYTES:
            raise ValueError("HBM address outside 2 GiB")
        return address // LINE_BYTES

    @staticmethod
    def _cycle(cycle: int) -> int:
        if type(cycle) is not int or cycle < 0:
            raise ValueError("Invalid cache cycle")
        return cycle

    def _event(self, finish: int, priority: int, kind: str, line: int, lookup: int = -1):
        heappush(self._events, (finish, priority, self._order, kind, line, lookup))
        self._order += 1

    def _advance(self, cycle: int):
        if cycle < self._resolved_through:
            raise ValueError("Cache events must be resolved in chronological order")
        while self._events and self._events[0][0] <= cycle:
            finish, _, _, kind, line, lookup = heappop(self._events)
            set_index, _, tag = self.locate(line * LINE_BYTES)
            ways = self.sets.get(set_index)
            if kind == "invalidate":
                self._last_invalidation[line] = finish
                if ways is not None and tag in ways:
                    del ways[tag]
                    self.traffic.invalidations += 1
            else:
                self.traffic.fills += 1
                self.traffic.cache_fill_bytes += LINE_BYTES
                if self._last_invalidation.get(line, -1) <= lookup:
                    # A write completed after the miss lookup: its old HBM
                    # response still consumes the fill bank but cannot install
                    # a stale copy in the cache.
                    if ways is None:
                        ways = self.sets.setdefault(set_index, OrderedDict())
                    if tag in ways:
                        ways.move_to_end(tag)
                    else:
                        if len(ways) == WAYS:
                            ways.popitem(last=False)
                        ways[tag] = None
        self._resolved_through = cycle

    def _reserve_bank(self, bank: int, earliest: int) -> int:
        return self._bank_busy[bank].reserve(earliest, 1)[0]

    def request_read(
        self,
        address: int,
        arrival: int,
        miss_ready: Callable[[int, int], int],
    ) -> tuple[int, bool, bool]:
        """Schedule one line read and return its source ready cycle."""
        line = self._line(address)
        arrival = self._cycle(arrival)
        line_address = line * LINE_BYTES
        t = self.traffic
        if not self.set_count:
            ready = self._cycle(miss_ready(line_address, arrival))
            if ready < arrival:
                raise ValueError("HBM completed before cache-off request")
            t.bypass_reads += 1
            t.hbm_read_bytes += LINE_BYTES
            self.last_access = CacheAccess(None, None, ready, False, True)
            return ready, False, True

        pending = self.reserve_lookup(address, arrival)
        return self.resolve_lookup(pending, miss_ready)

    def reserve_lookup(self, address: int, arrival: int) -> PendingLookup:
        """Reserve a bank slot without resolving tags ahead of other events."""
        if not self.set_count:
            raise ValueError("Cache-off requests have no lookup")
        line = self._line(address)
        arrival = self._cycle(arrival)
        if arrival < self._resolved_through:
            raise ValueError("Cache arrivals must be chronological")
        _, bank, _ = self.locate(address)
        return PendingLookup(line, self._reserve_bank(bank, arrival))

    def resolve_lookup(
        self,
        pending: PendingLookup,
        miss_ready: Callable[[int, int], int],
    ) -> tuple[int, bool, bool]:
        """Resolve a reserved lookup when its cycle reaches the event queue."""
        if not self.set_count or not isinstance(pending, PendingLookup):
            raise ValueError("Invalid pending cache lookup")
        line, lookup = pending.line, pending.cycle
        line_address = line * LINE_BYTES
        t = self.traffic
        set_index, bank, tag = self.locate(line * LINE_BYTES)
        self._advance(lookup)
        t.queries += 1
        ways = self.sets.get(set_index)
        if ways is not None and tag in ways:
            ways.move_to_end(tag)
            t.hits += 1
            t.cache_read_bytes += LINE_BYTES
            self.last_access = CacheAccess(lookup, None, lookup + HIT_LATENCY, True, False)
            return lookup + HIT_LATENCY, True, False

        t.misses += 1
        t.hbm_read_bytes += LINE_BYTES
        earliest_hbm = lookup + HIT_LATENCY
        hbm_done = self._cycle(miss_ready(line_address, earliest_hbm))
        if hbm_done < earliest_hbm:
            raise ValueError("HBM completed before cache miss request")
        fill_begin = self._reserve_bank(bank, hbm_done)
        fill_done = fill_begin + 1
        self._event(fill_done, 0, "fill", line, lookup)
        self.last_access = CacheAccess(lookup, fill_begin, fill_done, False, True)
        return fill_done, False, True

    def schedule_write_invalidate(self, address: int, finish: int) -> None:
        """Invalidate one line when its bypassed HBM write completes."""
        line = self._line(address)
        finish = self._cycle(finish)
        if not self.set_count:
            return
        if finish < self._resolved_through:
            raise ValueError("Cannot schedule a retroactive cache invalidation")
        self._event(finish, 1, "invalidate", line)

    def drain(self, through: int) -> None:
        """Apply pending fills and invalidations through a known cycle."""
        self._advance(self._cycle(through))
    def _available_slot(self, sm: int, earliest: int):
        choices = []
        for engine in range(self.hw.dma_engines):
            for slot, held in enumerate(self.dma_slots[sm][engine]):
                if isinstance(held, PendingTransfer):
                    continue
                slice_ready = self.dma_slice[sm][engine].first_free(earliest + 4, 1) - 4
                choices.append((max(held, slice_ready), engine, slot))
        return min(choices) if choices else None

    def _pending_hazard(self, reads, writes) -> bool:
        for transfer in self.pending:
            if any(_overlap(operand, transfer.dst) for operand in (*reads, *writes)):
                return True
            if transfer.src["space"] == "HBM" and any(
                _overlap(operand, transfer.src) for operand in writes
            ):
                return True
        return False

    def _operands(self, ins: Instruction):
        op, args = ins.op, ins.args
        if op in ("LD", "ST"):
            return [args["src"]], [args["dst"]]
        if op == "MMA.ACC":
            return [args["a"], args["b"], args["acc"]], [args["acc"]]
        if op == "VEC":
            return args["src"], [args["dst"]]
        return [args["src"]], [args["dst"]]

    def _preview(self, tape: GroupTape):
    def _issue(self, preview):
        from .pipeline import _GroupTimes, _MemoryTimes

        begin, pc, tape, selected = preview
        if begin < self.current_cycle:
            raise AssertionError("Instruction issued before global event time")
        self.current_cycle = begin
        ins = tape.next_command()[1]
        op = ins.op
        for sm in {peer.sm for peer in selected if not peer.control}:
            actual, _ = self.issue_free[sm].reserve(begin, 1)
            if actual != begin:
                raise AssertionError("Issue calendar changed after preview")
            self._busy(sm, "issue", 1)
        self.issue_sequence += 1
        sequence = self.issue_sequence
        if op == "WG.BEGIN":
            group = _GroupTimes(
                tape.name,
                tape.sm,
                16384 // self.hw.vector_lanes,
                begin + 1,
                begin + 1,
                _MemoryTimes.sized(65536 // 4),
                _MemoryTimes.sized(tape.shared_bytes // 4),
            )
            self.group_states[tape] = group
            self.resident_by_sm[tape.sm].add(tape)
            self.last_finish = max(self.last_finish, begin + 1)
        elif op == "WG.END":
            self.resident_by_sm[tape.sm].remove(tape)
            del self.group_states[tape]
            tape.end_cycle = begin + 1
            self.last_finish = max(self.last_finish, begin + 1)
        elif op in ("WAIT", "BARRIER", "STEP.COMMIT"):
            for peer in selected:
                if not peer.control:
                    self.group_states[peer].next_issue = begin + 1
            if op == "STEP.COMMIT":
                self.commit_finish[id(ins)] = begin + 1
            self.last_finish = max(self.last_finish, begin + 1)
        else:
            group = self.group_states[tape]
            self._stat_sm(tape.sm)["issue_wait_cycles"] += max(0, begin - group.next_issue)
            group.next_issue = begin + 1
            self._stat_sm(tape.sm)["instructions"] += 1
            if op in ("LD", "ST"):
                self._issue_transfer(tape, pc, ins, begin, sequence)
            else:
                self._issue_compute(tape, pc, ins, begin)
        for peer in selected:
            peer.commands[peer.cursor] = None
            peer.cursor += 1

    def _issue_compute(self, tape: GroupTape, pc: int, ins: Instruction, begin: int):
    def run(self) -> PerfResult:
        while True:
            candidates = [
                candidate
                for tape in self.queues.groups
                if (candidate := self._preview(tape)) is not None
            ]
            event_cycle = self.queue.next_cycle()
            if not candidates and event_cycle is None:
                if all(tape.next_command() is None for tape in self.queues.groups):
                    break
                blocked = [
                    (tape.name, tape.next_command()[1].op)
                    for tape in self.queues.groups
                    if tape.next_command() is not None
                ]
                raise ValueError(f"Pipeline deadlock: {blocked[:8]}")
            next_instruction = (
                min(candidates, key=lambda item: (item[0], item[1], item[2].sm))
                if candidates
                else None
            )
            if event_cycle is not None and (
                next_instruction is None or event_cycle <= next_instruction[0]
            ):
                self.current_cycle = max(self.current_cycle, self.queue.pop())
            else:
                self._issue(next_instruction)
        if self.pending:
            raise AssertionError("Pending DMA after all program commands")
        if self.step_requirements is not None and len(self.commit_finish) != len(
            self.step_requirements
        ):
            raise ValueError("Required step commitments incomplete")
        self.cache.drain(self.last_finish)
        if self.cache.traffic.hits + self.cache.traffic.misses != self.cache.traffic.queries:
            raise AssertionError("Cache query counters do not balance")
        if not self.hw.cache_mib and self.cache.traffic.bypass_reads * 64 != self.hbm_read_bytes:
            raise AssertionError("Bypassed read lines do not balance HBM traffic")
        for sm in range(self.hw.sm_count):
            stats = self.stats["sms"].get(str(sm))
            if stats is None:
                continue
            busy = stats["busy_cycles"]
            busy["issue"] = self.issue_free[sm].busy_cycles()
            busy["rf_read"] = self.rf_read[sm][0].busy_cycles()
            busy["rf_write"] = self.rf_write[sm][0].busy_cycles()
            busy["tc"] = self.tc[sm][0].busy_cycles()
            busy["vec"] = self.vec[sm][0].busy_cycles()
            busy["sfu"] = self.sfu[sm][0].busy_cycles()
            if self.hw.reduction_units:
                busy["reduce"] = self.reduce[sm][0].busy_cycles()
            busy["dma"] = sum(item.busy_cycles() for item in self.dma_slice[sm])
            busy["noc_in"] = self.sm_noc_in[sm].busy_cycles()
            busy["noc_out"] = self.sm_noc_out[sm].busy_cycles()
            if self.hw.shared_banks:
                busy["shared_read"] = sum(item.busy_cycles() for item in self.shared_read[sm])
                busy["shared_write"] = sum(item.busy_cycles() for item in self.shared_write[sm])
            stats["busy_cycles_kind"] = "sum_of_entity_cycles"
            capacities = {resource: 1 for resource in busy}
            capacities["dma"] = self.hw.dma_engines
            if self.hw.shared_banks:
                capacities["shared_read"] = self.hw.shared_banks
                capacities["shared_write"] = self.hw.shared_banks
            stats["entity_count"] = capacities
            stats["utilization"] = {
                resource: used / (self.last_finish * capacities[resource])
                for resource, used in busy.items()
            }
        shared = self.stats["shared"]
        shared["busy_cycles"]["noc"] = self.noc.busy_cycles()
        for channel, calendars in enumerate(self.hbm_channels):
            shared["busy_cycles"][f"hbm_channel_{channel}"] = calendars[0].busy_cycles()
        for bank, calendar in enumerate(self.cache._bank_busy):
            if self.hw.cache_mib:
                shared["busy_cycles"][f"cache_bank_{bank}"] = calendar.busy_cycles()
        shared["busy_cycles_kind"] = "sum_of_entity_cycles"
        shared["entity_count"] = {resource: 1 for resource in shared["busy_cycles"]}
        shared["utilization"] = {
            resource: used / self.last_finish for resource, used in shared["busy_cycles"].items()
        }
        shared["cache_queries"] = self.cache.traffic.queries
        shared["cache_hits"] = self.cache.traffic.hits
        shared["cache_misses"] = self.cache.traffic.misses
        shared["cache_bypass_reads"] = self.cache.traffic.bypass_reads
        shared["cache_fills"] = self.cache.traffic.fills
        shared["cache_invalidations"] = self.cache.traffic.invalidations
        shared["cache_read_bytes"] = self.cache.traffic.cache_read_bytes
        shared["cache_fill_bytes"] = self.cache.traffic.cache_fill_bytes
        shared["hbm_read_bytes"] = self.hbm_read_bytes
        shared["hbm_write_bytes"] = self.hbm_write_bytes
        shared["critical_completion"] = {"cycle": self.last_finish}
        shared["reservation_intervals"] = {
            "noc": self.noc.interval_count,
            "hbm_channels": [item[0].interval_count for item in self.hbm_channels],
            "sm_noc_in": [item.interval_count for item in self.sm_noc_in],
            "sm_noc_out": [item.interval_count for item in self.sm_noc_out],
            "energy_events": len(self.energy_events),
        }
        area = self.hw.area_mm2()
        seconds = self.last_finish / self.cost["clock_hz"]
        static_power = self.hw.static_power_w()
        peak_window_w, peak_instant_w = power_profile_w(area, self.energy_events)
        if self.energy_trace is not None:
            self.energy_trace.extend(self.energy_events)
        if abs(sum(event.dynamic_pj for event in self.energy_events) - self.dynamic_energy) > max(
            1e-6, self.dynamic_energy * 1e-9
        ):
            raise AssertionError("Dynamic energy events do not balance")
        self.stats["timeline"] = self._make_timeline(static_power, peak_window_w)
        return PerfResult(
            cycles=self.last_finish,
            dynamic_energy_pj=self.dynamic_energy,
            total_energy_pj=self.dynamic_energy + static_power * seconds * 1e12,
            average_power_w=self.dynamic_energy * 1e-12 / seconds + static_power,
            peak_window_power_w=peak_window_w,
            peak_power_upper_bound_w=peak_instant_w,
            area_mm2=area,
            instruction_count=self.queues.instruction_count,
            hbm_read_bytes=self.hbm_read_bytes,
            hbm_write_bytes=self.hbm_write_bytes,
            cache_hits=self.cache.traffic.hits,
            cache_misses=self.cache.traffic.misses,
            resource_stats=self.stats,
        )
"""Deterministic 2 GiB HBM symbol layout for the active challenge scenarios."""

from dataclasses import dataclass
from math import prod

from .workload import SCENARIOS, Model

HBM_BYTES = 2 * 1024**3
ALIGNMENT = 64


@dataclass(frozen=True)
class Symbol:
    name: str
    address: int
    shape: tuple[int, ...]
    readonly: bool
    release_step: int

    @property
    def nbytes(self) -> int:
        return prod(self.shape) * 4


class Layout:
    def __init__(self, symbols: list[Symbol]):
        self.symbols = {item.name: item for item in symbols}
        if len(self.symbols) != len(symbols):
            raise ValueError("Duplicate ABI symbol")
        self.total_bytes = max((s.address + s.nbytes for s in symbols), default=0)
        if self.total_bytes > HBM_BYTES:
            raise ValueError("ABI exceeds 2 GiB HBM")

    def address(
        self, name: str, index: tuple[int, ...], committed_steps: int, write: bool = False
    ) -> int:
        if name not in self.symbols:
            raise ValueError(f"Unknown ABI symbol: {name}")
        symbol = self.symbols[name]
        if write and symbol.readonly:
            raise ValueError("Write to read-only ABI symbol")
        if type(committed_steps) is not int or committed_steps < symbol.release_step:
            raise ValueError("Input not released yet")
        if len(index) != len(symbol.shape) or any(
            type(i) is not int or not 0 <= i < n for i, n in zip(index, symbol.shape)
        ):
            raise ValueError("ABI index out of bounds")
        offset = 0
        for i, extent in zip(index, symbol.shape):
            offset = offset * extent + i
        return symbol.address + offset * 4


def build_layout(model: Model, scenario: str) -> Layout:
    if scenario not in SCENARIOS or model.width % model.heads:
        raise ValueError("Unknown scenario or invalid model")
    batch, context, new_positions = SCENARIOS[scenario]
    prefill = scenario.startswith("P")
    d, f, h, hd = model.width, model.ffn, model.heads, model.head_width
    symbols = []
    cursor = 0

    def add(name: str, shape: tuple[int, ...], readonly: bool, release_step: int = 0):
        nonlocal cursor
        cursor = (cursor + ALIGNMENT - 1) // ALIGNMENT * ALIGNMENT
        symbols.append(Symbol(name, cursor, shape, readonly, release_step))
        cursor += prod(shape) * 4

    for layer in range(model.layers):
        prefix = f"layer{layer}"
        for name, shape in (
            ("ln1_g", (d,)),
            ("ln1_b", (d,)),
            ("wqkv", (d, 3 * d)),
            ("wo", (d, d)),
            ("ln2_g", (d,)),
            ("ln2_b", (d,)),
            ("w1", (d, f)),
            ("b1", (f,)),
            ("w2", (f, d)),
            ("b2", (d,)),
        ):
            add(f"{prefix}/{name}", shape, True)
        if not prefill:
            add(f"{prefix}/history_k", (batch, h, context, hd), True)
            add(f"{prefix}/history_v", (batch, h, context, hd), True)
    if prefill:
        add("input/prompt", (batch, context, d), True)
        add("input/step0", (batch, d), True, 1)
        add("output/hidden", (batch, context + 1, d), False)
        kv_steps = context + 1
    else:
        for step in range(new_positions):
            add(f"input/step{step}", (batch, d), True, step)
        add("output/hidden", (batch, new_positions, d), False)
        kv_steps = new_positions
    for layer in range(model.layers):
        for kind in ("k", "v"):
            add(f"layer{layer}/new_{kind}", (batch, h, kv_steps, hd), False)
    scratch_start = (cursor + ALIGNMENT - 1) // ALIGNMENT * ALIGNMENT
    add("scratch", ((HBM_BYTES - scratch_start) // 4,), False)
    return Layout(symbols)

