"""Instruction pipeline timing for the programmable Transformer challenge.

Functional execution remains in ``micro.py``. This module schedules the same
parsed instructions against issue, RF, execution, DMA, NoC and HBM resources.
The functional executor remains the authority on FP32 results. Timing uses
the same parsed instruction stream and explicit resource calendars.
"""

from dataclasses import dataclass
from math import prod
from tempfile import TemporaryFile

import numpy as np

from .hardware import Hardware
from .perf import PerfResult
from .power import EnergyEvent
from .resource_calendar import IntervalCalendar


@dataclass
class _MemoryTimes:
    written: np.ndarray
    read_until: np.ndarray
    backing: object | None = None

    @classmethod
    def sized(cls, words: int, sparse: bool = False):
        if sparse:
            # The ABI permits addresses near 2 GiB. A dense pair of int64
            # hazard arrays would occupy 8 GiB even if only a few words are
            # touched. Truncated temporary files are sparse and unlinked on
            # close; ndarray and strided-view operations retain their exact
            # element semantics while only visited pages consume storage.
            backing = TemporaryFile()
            backing.truncate(words * 16)
            written = np.memmap(backing, dtype=np.int64, mode="r+", shape=words, offset=0)
            read_until = np.memmap(
                backing, dtype=np.int64, mode="r+", shape=words, offset=words * 8
            )
            return cls(written, read_until, backing)
        return cls(np.zeros(words, np.int64), np.zeros(words, np.int64))

    def view(self, operand):
        offset = operand["offset"]
        shape = operand.get("shape", [operand["count"]])
        strides = operand.get("strides", [1])
        if (
            type(offset) is not int
            or offset < 0
            or type(operand["count"]) is not int
            or operand["count"] <= 0
            or not isinstance(shape, list)
            or not isinstance(strides, list)
            or len(shape) not in (1, 2)
            or len(shape) != len(strides)
            or any(type(x) is not int or x <= 0 for x in shape + strides)
            or prod(shape) != operand["count"]
        ):
            raise ValueError("Invalid timed memory view")
        span = 1 + sum((extent - 1) * stride for extent, stride in zip(shape, strides))
        if offset < 0 or offset + span > self.written.size:
            raise ValueError("Timed memory view out of bounds")
        if len(shape) == 1 and strides == [1]:
            return self.written[offset : offset + span], self.read_until[offset : offset + span]
        byte_strides = tuple(stride * 8 for stride in strides)
        return (
            np.lib.stride_tricks.as_strided(
                self.written[offset : offset + span], shape=shape, strides=byte_strides
            ),
            np.lib.stride_tricks.as_strided(
                self.read_until[offset : offset + span], shape=shape, strides=byte_strides
            ),
        )


@dataclass
class _GroupTimes:
    name: str
    sm: int
    words_per_lane: int
    next_issue: int
    last_finish: int
    rf: _MemoryTimes
    shared: _MemoryTimes


def _view(group: _GroupTimes, hbm: _MemoryTimes, operand):
    if operand["space"] == "HBM":
        if operand["wg"] is not None or operand["lane"] != 0:
            raise ValueError("HBM address/scope invalid")
        return hbm.view(operand)
    if operand["wg"] != group.name:
        raise ValueError("Cross-workgroup timed access")
    if operand["space"] == "RF":
        lane = operand["lane"]
        shape = operand.get("shape", [operand["count"]])
        strides = operand.get("strides", [1])
        span = 1 + sum((extent - 1) * stride for extent, stride in zip(shape, strides))
        if type(lane) is not int or not 0 <= lane < 16384 // group.words_per_lane:
            raise ValueError("RF lane invalid")
        if operand["offset"] + span > group.words_per_lane:
            raise ValueError("RF lane view out of bounds")
        adjusted = operand | {"offset": operand["offset"] + operand["lane"] * group.words_per_lane}
        return group.rf.view(adjusted)
    if operand["space"] == "SH":
        if operand["lane"] != 0:
            raise ValueError("Shared lane invalid")
        return group.shared.view(operand)
    raise ValueError("Invalid timed memory space")


def _max_write(group, hbm, operand):
    if "imm" in operand:
        return 0
    return int(_view(group, hbm, operand)[0].max())


def _max_destination(group, hbm, operand):
    written, read_until = _view(group, hbm, operand)
    return max(int(written.max()), int(read_until.max()))


def _mark(group, hbm, reads, writes, read_finish, write_finish):
    for operand in reads:
        if "imm" not in operand:
            read_until = _view(group, hbm, operand)[1]
            np.maximum(read_until, read_finish, out=read_until)
    for operand in writes:
        _view(group, hbm, operand)[0][...] = write_finish


def _reserve(free: list[IntervalCalendar], earliest: int, duration: int):
    if duration == 0:
        return earliest
    def _preview(self, tape: GroupTape):
        from .pipeline import _max_destination, _max_write

        command = tape.next_command()
        if command is None:
            return None
        pc, ins = command
        op, args = ins.op, ins.args
        if op == "WG.BEGIN":
            if tape.predecessor is not None and tape.predecessor.end_cycle is None:
                return None
            if (
                tape.start_after_commit is not None
                and tape.start_after_commit not in self.commit_finish
            ):
                return None
            residents = self.resident_by_sm[tape.sm]
            if (
                len(residents) >= 4
                or args["shared_bytes"] + sum(peer.shared_bytes for peer in residents)
                > self.hw.shared_kib * 1024
            ):
                return None
            ready = max(
                tape.predecessor.end_cycle if tape.predecessor is not None else 0,
                self.commit_finish.get(tape.start_after_commit, 0),
            )
            selected = (tape,)
        elif op in ("WAIT", "BARRIER", "STEP.COMMIT"):
            selected = self.queues.sync_participants[id(ins)]
            if self.hw.dma_depth == 0 and any(
                transfer.tape in selected for transfer in self.pending
            ):
                return None
            if any(
                peer.next_command() is None or peer.next_command()[1] is not ins
                for peer in selected
            ):
                return None
            if tape is not selected[0]:
                return None
            if op == "STEP.COMMIT":
                if self.pending:
                    return None
                if (
                    self.step_requirements is not None
                    and args["step"] not in self.step_requirements
                ):
                    raise ValueError("Invalid step commitment")
                closed = self.queues.commit_closed[id(ins)]
                if any(peer.end_cycle is None for peer in closed):
                    return None
                if tape.control and (
                    tape.start_after_commit is not None
                    and tape.start_after_commit not in self.commit_finish
                ):
                    return None
                ranges = (
                    self.step_requirements.get(args["step"], [])
                    if self.step_requirements is not None
                    else []
                )
                if any(not self.hbm.written[lo:hi].all() for lo, hi in ranges):
                    raise ValueError("Step outputs incomplete")
                target = max((int(self.hbm.written[lo:hi].max()) for lo, hi in ranges), default=0)
                target = max(
                    target,
                    *(self.group_states[peer].last_finish for peer in selected if not peer.control),
                    *(peer.end_cycle for peer in closed),
                    self.commit_finish.get(tape.start_after_commit, 0),
                )
            else:
                names = args["events"]
                if any(name not in self.events for name in names):
                    return None
                target = max((self.events[name] for name in names), default=0)
                if op == "BARRIER":
                    if any(transfer.tape in selected for transfer in self.pending):
                        return None
                    target = max(
                        target, *(self.group_states[peer].last_finish for peer in selected)
                    )
            ready = max(
                [target]
                + [self.group_states[peer].next_issue for peer in selected if not peer.control]
            )
        else:
            group = self.group_states[tape]
            selected = (tape,)
            if self.hw.dma_depth == 0 and any(transfer.tape is tape for transfer in self.pending):
                return None
            if op in ("LD", "ST") and all(
                isinstance(held, PendingTransfer)
                for engine in self.dma_slots[tape.sm]
                for held in engine
            ):
                return None
            if op == "WG.END":
                if any(transfer.tape is tape for transfer in self.pending):
                    return None
                ready = max(group.next_issue, group.last_finish)
            else:
                reads, writes = self._operands(ins)
                if self._pending_hazard(reads, writes):
                    return None
                ready = max(
                    group.next_issue,
                    *(_max_write(group, self.hbm, operand) for operand in reads),
                    *(_max_destination(group, self.hbm, operand) for operand in writes),
                )
                if op in ("LD", "ST"):
                    slot = self._available_slot(tape.sm, ready)
                    if slot is None:
                        return None
                    ready = max(ready, slot[0])
        sms = {peer.sm for peer in selected if not peer.control}
        begin = max(ready, self.current_cycle)
        while sms:
            candidate = max(self.issue_free[sm].first_free(begin, 1) for sm in sms)
            if candidate == begin:
                break
            begin = candidate
        return begin, pc, tape, selected

